import{_ as e,o,c,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"调试示例","description":"您正确指出了我的解释中的一个不精确之处。我在之前的描述中没有清晰地展示逆序更新的过程。在逆序更新 dp 数组时，确实应该是从高到低的预算进行更新，这是为了确保每件物品在每个预算限制下只被计算一次，避免同一物品在同一预算下被重复使用。我们重新正确地描述这个过程： 正确的更新过程 对。","frontmatter":{"title":"调试示例","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"您正确指出了我的解释中的一个不精确之处。我在之前的描述中没有清晰地展示逆序更新的过程。在逆序更新 dp 数组时，确实应该是从高到低的预算进行更新，这是为了确保每件物品在每个预算限制下只被计算一次，避免同一物品在同一预算下被重复使用。我们重新正确地描述这个过程： 正确的更新过程 对。","sidebarWeight":3,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/HJ16 购物单/调试示例.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/HJ16 购物单/调试示例.md","filePath":"posts/前端面试与实战/03-算法训练/HJ16 购物单/调试示例.md"}'),p={name:"posts/前端面试与实战/03-算法训练/HJ16 购物单/调试示例.md"};function l(i,d,t,r,s,n){return o(),c("div",null,[...d[0]||(d[0]=[a('<div><h1 id="调试示例" tabindex="-1">调试示例 <a class="header-anchor" href="#调试示例" aria-label="Permalink to &quot;调试示例&quot;">​</a></h1><blockquote><p>本节目标：理解“调试示例”的核心思路，并能把它用于实际开发或面试表达。 您正确指出了我的解释中的一个不精确之处。我在之前的描述中没有清晰地展示逆序更新的过程。在逆序更新 <code>dp</code> 数组时，确实应该是从高到低的预算进行更新，这是为了确保每件物品在每个预算限制下只被计算一次，避免同一物品在同一预算下被重复使用。我们重新正确地描述这个过程：</p></blockquote><h3 id="正确的更新过程" tabindex="-1">正确的更新过程 <a class="header-anchor" href="#正确的更新过程" aria-label="Permalink to &quot;正确的更新过程&quot;">​</a></h3><p>对于每件物品，我们确实应该从最大预算开始向下到该物品价格所需的最小预算进行更新。这样做可以确保在计算更低预算的可能性时，较高预算的结果不会受到未处理的物品影响。这是一种典型的“不放回”背包问题处理方式。</p><p>以下是如何正确地从高到低更新 <code>dp</code> 数组：</p><p>假设我们有两个主件：</p><ul><li><strong>主件A</strong>: 价格 <code>20</code> 元，重要度 <code>3</code>，对应的简化单位价值为 <code>60</code>。</li><li><strong>主件B</strong>: 价格 <code>10</code> 元，重要度 <code>2</code>，对应的简化单位价值为 <code>20</code>。</li></ul><p>总预算为 <code>50</code> 元，简化后为 <code>5</code> 单位。</p><h4 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h4><ul><li><code>dp = [0, 0, 0, 0, 0, 0]</code> 对应于预算 <code>0</code> 到 <code>5</code>。</li></ul><h4 id="更新过程-逆序-对于主件a" tabindex="-1">更新过程（逆序）对于主件A： <a class="header-anchor" href="#更新过程-逆序-对于主件a" aria-label="Permalink to &quot;更新过程（逆序）对于主件A：&quot;">​</a></h4><ul><li>假设 <code>dp</code> 当前为 <code>[0, 0, 0, 0, 0, 0]</code></li><li><strong>从高到低更新</strong>，开始更新从 <code>dp[5]</code> 到 <code>dp[2]</code> (因为主件A的价格为 <code>2</code>，即 <code>20</code> 元)：</li><li><code>dp[5] = max(dp[5], dp[5-2] + 60) = max(0, 0 + 60) = 60</code></li><li><code>dp[4] = max(dp[4], dp[4-2] + 60) = max(0, 0 + 60) = 60</code></li><li><code>dp[3] = max(dp[3], dp[3-2] + 60) = max(0, 0 + 60) = 60</code></li><li><code>dp[2] = max(dp[2], dp[2-2] + 60) = max(0, 0 + 60) = 60</code></li></ul><p>此时 <code>dp</code> 数组变为 <code>[0, 0, 60, 60, 60, 60]</code>。</p><h4 id="更新过程-逆序-对于主件b" tabindex="-1">更新过程（逆序）对于主件B： <a class="header-anchor" href="#更新过程-逆序-对于主件b" aria-label="Permalink to &quot;更新过程（逆序）对于主件B：&quot;">​</a></h4><ul><li>继续从更新过的 <code>dp</code> 数组 <code>[0, 0, 60, 60, 60, 60]</code> 开始：</li><li><code>dp[5] = max(dp[5], dp[5-1] + 20) = max(60, 60 + 20) = 80</code></li><li><code>dp[4] = max(dp[4], dp[4-1] + 20) = max(60, 60 + 20) = 80</code></li><li><code>dp[3] = max(dp[3], dp[3-1] + 20) = max(60, 0 + 20) = 60</code></li><li><code>dp[2] = max(dp[2], dp[2-1] + 20) = max(60, 0 + 20) = 60</code></li><li><code>dp[1] = max(dp[1], dp[1-1] + 20) = max(0, 0 + 20) = 20</code></li></ul><p>最终 <code>dp</code> 数组为 <code>[0, 20, 60, 60, 80, 80]</code>。</p><h4 id="解释" tabindex="-1">解释 <a class="header-anchor" href="#解释" aria-label="Permalink to &quot;解释&quot;">​</a></h4><p>通过逆序更新，我们确保了不会重复使用同一物品来更新同一预算多次。逆序更新是在背包问题中处理不可重复使用物品的关键技巧。这样，最终的 <code>dp[5]</code> 值 <code>80</code> 代表了在 <code>50</code> 元预算内通过购</p><p>买这些物品能获得的最大满意度，可能包括多种物品的组合。</p><p>在动态规划解法中，对于背包问题，<code>dp[i]</code> 表示在给定预算（或重量、容量等限制条件）<code>i</code> 下能够获得的最大满意度（或最大价值、最小成本等）。当我们在更新 <code>dp[5]</code> 时使用表达式 <code>dp[5] = max(dp[5], dp[5-1] + 20)</code>，这里的 <code>dp[5-1]</code> 具体含义如下：</p><h3 id="解释-dp-5-1" tabindex="-1">解释 <code>dp[5-1]</code> <a class="header-anchor" href="#解释-dp-5-1" aria-label="Permalink to &quot;解释 `dp[5-1]`&quot;">​</a></h3><ol><li><p><strong>当前预算为 <code>5</code></strong>: 在我们的简化单位中（每单位代表 <code>10</code> 元），<code>5</code> 单位预算代表实际的 <code>50</code> 元。因此，<code>dp[5]</code> 指的是在有 <code>50</code> 元预算下能够达到的最大满意度。</p></li><li><p><strong>表达式中的 <code>dp[5-1]</code></strong>: 这里的 <code>dp[5-1]</code> 或 <code>dp[4]</code> 代表在预算为 <code>40</code> 元（简化单位为 <code>4</code>）时可以达到的最大满意度。</p></li></ol><h3 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h3><p>在更新 <code>dp[5]</code> 的过程中，我们考虑：</p><ul><li>不购买当前物品（维持 <code>dp[5]</code> 当前的值，这个值已经是之前考虑过的所有可能的最大满意度）</li><li>购买当前正在考虑的物品（假设其价值为 <code>20</code> 满意度，价格为 <code>10</code> 元）</li></ul><p>通过表达式 <code>dp[5] = max(dp[5], dp[4] + 20)</code>，我们实际在做的比较是：</p><ul><li><strong><code>dp[5]</code></strong>: 直接从 <code>dp</code> 数组当前的第 <code>5</code> 项获取，这反映了如果不购买当前物品（或在没有当前物品的情况下）在 <code>50</code> 元预算下的最大满意度。</li><li><strong><code>dp[4] + 20</code></strong>: 表示如果决定购买这个物品，那么需要先考虑在剩余的 <code>40</code> 元预算（<code>50 - 10</code>）下的最大满意度（从 <code>dp[4]</code> 获得），然后加上当前物品带来的 <code>20</code> 满意度。</li></ul><h3 id="为什么这样更新" tabindex="-1">为什么这样更新？ <a class="header-anchor" href="#为什么这样更新" aria-label="Permalink to &quot;为什么这样更新？&quot;">​</a></h3><p>这种更新方式确保了每种预算下的最大满意度都被考虑到。通过从后向前更新，我们可以保证在计算 <code>dp[j]</code>（<code>j</code> 表示当前考虑的预算单位）时，使用的 <code>dp[j - cost]</code>（<code>cost</code> 是当前物品价格的单位）是一个不包含当前物品的状态，从而保证每件物品只被计算一次。这是解决不可重复使用物品的背包问题的标准方法。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p><code>dp[5-1]</code> 或 <code>dp[4]</code> 在 <code>dp[5]</code> 更新中的使用，展示了如何将当前物品的价值添加到已知的更小预算的最优解中，从而探索是否包括当前物品能够得到更好的满意度。这种方法充分利用了动态规划的优势，通过构建从小到大的解决方案，最终得到全局最优解。</p></div>',1)])])}const m=e(p,[["render",l]]);export{u as __pageData,m as default};
